from collections import Counter
def solve(g):
    H,W=len(g),len(g[0]); out=[row[:] for row in g]
    glob=Counter(x for row in g for x in row)
    for r in range(H):
        for c in range(W):
            nb=[g[rr][c] for rr in (r-1,r+1) if 0<=rr<H]+[g[r][cc] for cc in (c-1,c+1) if 0<=cc<W]
            cnt={}
            for x in nb: cnt[x]=cnt.get(x,0)+1
            m=max(cnt.values())
            winners=[k for k,v in cnt.items() if v==m]
            if g[r][c] in winners: continue
            if len(winners)==1: out[r][c]=winners[0]
            else: out[r][c]=min(winners,key=lambda k:glob[k])
    return out
